using System.Buffers.Binary;
using System.IO;
using System.Text;
using System.Text.Json;
using NAudio.Wave;
namespace MRS;
internal static class Update043Tests
{
 internal sealed class CaptureTransport:IPskTransport{internal readonly List<byte[]> Packets=[];internal bool Fail;public Task Send(byte[] bytes,CancellationToken token){token.ThrowIfCancellationRequested();if(Fail)throw new IOException("Synthetic offline transport");Packets.Add(bytes);return Task.CompletedTask;}public void Dispose(){}}
 internal static PacketObservation Row(string text="CQ K1ABC FN42",string mode="FT8",bool replay=false,long? hz=14074000,DateTimeOffset? utc=null,double? snr=-12){var now=utc??DateTimeOffset.UtcNow;double period=mode=="FT4"?7.5:15;return RadioDataParse.Json(JsonSerializer.Serialize(new{protocol=mode,text,audio_hz=1500,dt_error=-.09,snr_db=snr,mrs_slot=(long)(now.ToUnixTimeMilliseconds()/1000.0/period),mrs_epoch=2}),new("043-test","Synthetic fixture",replay,hz))!;}
 internal static void Run(Action<bool,string> check)
 {
  foreach(var example in new[]{("CQ WY0V EN12","WY0V","","EN12",true),("KJ4WXH WB3FME FM19","WB3FME","KJ4WXH","FM19",false),("CQ DX W2XYZ FN42","W2XYZ","","FN42",true),("K1ABC W2XYZ RR73","W2XYZ","K1ABC","",false),("<...> W2XYZ -10","W2XYZ","<...>","",false),("K1ABC <...> -10","<...>","K1ABC","",false)}){var p=Row(example.Item1);var d=p.Weak;check(d.Sender==example.Item2&&d.Destination==example.Item3&&d.Grid==example.Item4&&d.Cq==example.Item5,"Weak message semantics: "+example.Item1);check(p.From==d.Sender&&p.To==d.Destination,"Shared From/To parsed: "+example.Item1);}
  check(!Row("K1ABC <...> -10").Weak.SenderResolved,"Hashed/unresolved sender is never invented");check(!Row("HELLO WORLD").Weak.SenderResolved,"Free text is not a sender callsign");check(Row().Weak.Snr==-12&&Row(snr:null).Weak.Snr==null,"Measured SNR distinct from absent value; no sync-score substitution");
  var prefs=new WeakPreferences();prefs.Rules.Add(new(){Callsign="K1ABC",Color="Gold"});check(prefs.Highlight(Row().Weak)=="Gold","Watch highlight takes priority over CQ");prefs.Rules[0].Ignore=true;check(prefs.Ignored(Row().Weak),"Ignore rule matches transmitting sender");check(!prefs.Ignored(Row("K1ABC W2XYZ -10").Weak),"Sender ignore does not hide a station merely addressed");prefs.Rules[0].Match="Destination";check(prefs.Ignored(Row("K1ABC W2XYZ -10").Weak),"Explicit destination ignore supported");prefs.Rules[0].Match="Sender";prefs.Rules[0].BaseCall=true;check(prefs.Ignored(Row("CQ K1ABC/P FN42").Weak),"Portable/base matching is explicit");
  var track=new WeakTracking();track.Observe(Row());track.Observe(Row());track.Observe(Row("K1ABC W2XYZ RR73"));check(track.Stations.Count==2&&track.Stations.Single(s=>s.Callsign=="K1ABC").Count==2,"Tracking counts sender observations, not destination mentions");
  DateTimeOffset now=DateTimeOffset.UtcNow;var tx=new CaptureTransport();using var reporter=new PskReporter(tx);var settings=new PskSettings("W2XYZ","FN42ab","Synthetic SDR","Test antenna");reporter.Enable(settings);check(reporter.Queue(Row(utc:now),false,true,now),"Reporter accepts validated live FT8 with known source frequency");check(reporter.Queue(Row(utc:now),false,true,now)&&reporter.Queued==1,"Reporter coalesces repeated CQ decodes before upload");check(!reporter.Queue(Row(replay:true,utc:now),false,true,now),"Reporter excludes replay");check(!reporter.Queue(Row(hz:null,utc:now),false,true,now),"Reporter excludes audio without known RF frequency");check(!reporter.Queue(Row("K1ABC <...> -10",utc:now),false,true,now),"Reporter excludes unresolved transmitters");check(!reporter.Queue(Row(utc:now),true,true,now),"Reporter honors explicit ignored-row exclusion");
  check(reporter.Queue(Row("CQ N3TEST FM19",mode:"FT4",utc:now,snr:null),false,true,now),"Reporting works without SNR");reporter.Flush(now).GetAwaiter().GetResult();check(tx.Packets.Count==1&&reporter.Sent==2&&reporter.Queued==0,"Periodic reporting batch contains two stations, not one send per cycle");
  byte[] packet=tx.Packets[0];int U16(int at)=>BinaryPrimitives.ReadUInt16BigEndian(packet.AsSpan(at,2));check(U16(0)==10&&U16(2)==packet.Length&&packet.Length<=1200,"PSK IPFIX header length/network order and datagram bound");var sets=new Dictionary<int,byte[]>();for(int at=16;at<packet.Length;){int len=U16(at+2);check(len>=4&&len%4==0&&at+len<=packet.Length,"PSK set aligned and bounded");sets[U16(at)]=packet.AsSpan(at+4,len-4).ToArray();at+=len;}
  byte[] data=sets[PskWire.SenderSnr];int index=0;string Str(){int n=data[index++];string v=Encoding.UTF8.GetString(data,index,n);index+=n;return v;}check(Str()=="K1ABC","PSK sends actual transmitting callsign");long frequency=0;for(int n=0;n<5;n++)frequency=(frequency<<8)|data[index++];check(frequency==14075500,"PSK RF frequency includes USB audio offset");check(Str()=="FT8"&&data[index++]==1&&Str()=="FN42","PSK mode, automatic source and sender grid correctly encoded");index+=4;check(unchecked((sbyte)data[index])==-12,"PSK signed SNR encoded independently from synchronization score");check(Encoding.UTF8.GetString(sets[PskWire.Receiver]).Contains("M.R.S. 0.46.0-preview1")&&Encoding.UTF8.GetString(sets[PskWire.Receiver]).Contains("Synthetic SDR"),"PSK receiver metadata includes actual M.R.S. version and selected rig");
  check(!reporter.Queue(Row(utc:now),false,true,now.AddMinutes(1)),"Reporter suppresses repeat upload inside five minutes");reporter.Disable();reporter.Enable(settings);check(!reporter.Queue(Row(utc:now),false,true,now.AddMinutes(1)),"Reporting toggle does not defeat duplicate suppression");reporter.Disable();check(reporter.Queued==0&&!reporter.Enabled,"Reporting disable clears pending queue");
  tx.Fail=true;reporter.Enable(settings);check(reporter.Queue(Row("CQ N4TEST FN42",utc:now),false,true,now),"Synthetic failed-send test queued");reporter.Flush(now).GetAwaiter().GetResult();check(reporter.Queued==1&&reporter.Status.Contains("failed"),"Failed UDP reports remain queued without false delivery claim");using var disabled=new PskReporter(allowNetwork:false);bool denied=false;try{disabled.Enable(settings);}catch(IOException){denied=true;}check(denied,"Diagnostic profile cannot activate live PSK Reporter transport");
  string directory=Path.Combine(Path.GetTempPath(),"MRS-sort-043-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{string file=Path.Combine(directory,"order.json");File.WriteAllText(file,"false");var grid=new System.Windows.Controls.DataGrid();new System.Windows.Controls.Grid().Children.Add(grid);using var first=new MonitorOrder(grid,file);check(first.NewestFirst,"Legacy sort settings migrate once to newest first");first.SetNewest(false);var secondGrid=new System.Windows.Controls.DataGrid();new System.Windows.Controls.Grid().Children.Add(secondGrid);using var second=new MonitorOrder(secondGrid,file);check(!second.NewestFirst,"Explicit later oldest-first choice survives restart");}finally{Directory.Delete(directory,true);}
  Snr(check);
 }
 private static void Snr(Action<bool,string> check)
 {
  foreach(string mode in new[]{"FT8","FT4"})foreach(double target in (mode=="FT4"?new[]{-5.0,-10.0}:new[]{-5.0,-15.0})){
   using var wav=new WaveFileReader(Path.Combine(AppContext.BaseDirectory,"Docs","Samples","synthetic-"+mode.ToLowerInvariant()+".wav"));var provider=wav.ToSampleProvider();var samples=new float[wav.Length/2];int count=provider.Read(samples,0,samples.Length);double power=samples.Skip(18000).Take(18000).Average(x=>(double)x*x);double variance=power*12000/(5000*Math.Pow(10,target/10));var random=new Random(mode=="FT8"?430:431);for(int n=0;n<count;n++){double u=Math.Max(1e-12,random.NextDouble()),v=random.NextDouble();samples[n]+=(float)(Math.Sqrt(variance)*Math.Sqrt(-2*Math.Log(u))*Math.Cos(2*Math.PI*v));}
   var start=new System.Diagnostics.ProcessStartInfo(Path.Combine(AppContext.BaseDirectory,"Decoders","RadioData","mrs-weak.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add(mode);start.ArgumentList.Add("0");using var process=System.Diagnostics.Process.Start(start)!;byte[] bytes=new byte[count*4];Buffer.BlockCopy(samples,0,bytes,0,bytes.Length);process.StandardInput.BaseStream.Write(BitConverter.GetBytes(count));process.StandardInput.BaseStream.Write(bytes);process.StandardInput.Close();string output=process.StandardOutput.ReadToEnd();process.WaitForExit();var rows=output.Split('\n').Where(l=>l.Contains("CQ K1ABC FN42")).ToArray();check(process.ExitCode==0&&rows.Length>0,$"Known-noise {mode} waveform decodes at {target} dB");using var json=JsonDocument.Parse(rows[0]);double measured=json.RootElement.GetProperty("snr_db").GetDouble();check(Math.Abs(measured-target)<3.5,$"{mode} power-derived SNR {measured:0.0} within 3.5 dB of injected {target:0.0} dB (2500 Hz reference)");
  }
 }
}
